import 'dart:async';


void main() {
  final centroller = StreamController();
  final stream = centroller.stream.asBroadcastStream();

  //짝수
  final streamListener1 = stream.where((val) => val % 2 == 0).listen((val){
    print('listener 1: $val');
  });

  //홀수
  final streamListener2 = stream.where((val) => val % 2 == 1).listen((val){
    print('Listener 2: $val');
  });


  centroller.sink.add(1);
  centroller.sink.add(2);
  centroller.sink.add(3);
  centroller.sink.add(4);
  centroller.sink.add(5);


}

import 'dart:async';


void main() {
  calculate(2).listen((val){
    print('calculate(2) : $val');

  });

  calculate(4).listen((val){
    print('calculate(4) : $val');

  });
}

Stream<int> calculate(int number) async* {
  for(int i=0; i < 5; i++){
    yield i * number;

    await Future.delayed(Duration(seconds: 1));
  }
}

import 'dart:async';


void main() {
  playAllStream().listen((val){
    print(val);
  });

  calculate(2).listen((val){
    print('calculate(2) : $val');
  });

  calculate(4).listen((val){
    print('calculate(4) : $val');
  });


}

//동시x 하려면 ..?
Stream<int> playAllStream()async*{
  yield* calculate(2);
  yield* calculate(4);

}
Stream<int> calculate(int number) async* {
  for(int i=0; i < 5; i++){
    yield i * number;

    await Future.delayed(Duration(seconds: 1));
  }
}
